css:
.grid {
  height: 150px;
  display: grid;
  grid-template-columns: repeat(20, 1fr);
  column-gap: 14px;
}

.line {
  position: relative;
  width: 7px;
  height: 100%;
}

.line::before,
.line::after {
  content: "";
  position: absolute;
  width: 100%;
  height: 7px;
  border-radius: 7px;
  background-color: #3b44d1;
  animation: upper-line 4s ease-in-out infinite alternate;
}

.line::after {
  bottom: 0;
  background-color: #dc5245;
  height: calc(100% - 20px);
  animation: bottom-line 4s ease-in-out infinite alternate;
}

/* Delays */
.line:nth-child(1)::before,
.line:nth-child(1)::after {
  animation-delay: -0.1s;
}

.line:nth-child(2)::before,
.line:nth-child(2)::after {
  animation-delay: -0.2s;
}

.line:nth-child(3)::before,
.line:nth-child(3)::after {
  animation-delay: -0.3s;
}

.line:nth-child(4)::before,
.line:nth-child(4)::after {
  animation-delay: -0.4s;
}

.line:nth-child(5)::before,
.line:nth-child(5)::after {
  animation-delay: -0.5s;
}

.line:nth-child(6)::before,
.line:nth-child(6)::after {
  animation-delay: -0.6s;
}

.line:nth-child(7)::before,
.line:nth-child(7)::after {
  animation-delay: -0.7s;
}

.line:nth-child(8)::before,
.line:nth-child(8)::after {
  animation-delay: -0.8s;
}

.line:nth-child(9)::before,
.line:nth-child(9)::after {
  animation-delay: -0.9s;
}

.line:nth-child(10)::before,
.line:nth-child(10)::after {
  animation-delay: -1s;
}

.line:nth-child(11)::before,
.line:nth-child(11)::after {
  animation-delay: -1.1s;
}

.line:nth-child(12)::before,
.line:nth-child(12)::after {
  animation-delay: -1.2s;
}

.line:nth-child(13)::before,
.line:nth-child(13)::after {
  animation-delay: -1.3s;
}

.line:nth-child(14)::before,
.line:nth-child(14)::after {
  animation-delay: -1.4s;
}

.line:nth-child(15)::before,
.line:nth-child(15)::after {
  animation-delay: -1.5s;
}

.line:nth-child(16)::before,
.line:nth-child(16)::after {
  animation-delay: -1.6s;
}

.line:nth-child(17)::before,
.line:nth-child(17)::after {
  animation-delay: -1.7s;
}

.line:nth-child(18)::before,
.line:nth-child(18)::after {
  animation-delay: -1.8s;
}

.line:nth-child(19)::before,
.line:nth-child(19)::after {
  animation-delay: -1.9s;
}

.line:nth-child(20)::before,
.line:nth-child(20)::after {
  animation-delay: -2s;
}

@keyframes upper-line {
  50% {
    height: calc(100% - 13px);
  }

  100% {
    background-color: #46f443;
  }
}

@keyframes bottom-line {
  50% {
    height: 7px;
  }

  100% {
    background-color: #5b38ee;
  }
}
